import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    t = int(input_data[0])
    results = []

    idx = 1
    for _ in range(t):
        s = input_data[idx]
        idx += 1

        n = len(s)
        all_n = True
        for char in s:
            if char != 'N':
                all_n = False
                break

        if all_n:
            results.append("NO")
        else:
            results.append("YES")

    for res in results:
        print(res)

solve()
